// Airtable contract actions. Input: recordId. Secret: DULCY_SIGN_AIRTABLE_KEY.
const API_ORIGIN = 'https://sign.dulcy.io';
const TABLE_ID = 'tblFhsgZ970B44r1s';
const { recordId } = input.config();
const key = input.secret('DULCY_SIGN_AIRTABLE_KEY');
const table = base.getTable(TABLE_ID);
const record = await table.selectRecordAsync(recordId);
if (!record) throw new Error('Contract record not found.');
const text = name => record.getCellValueAsString(name).trim();
const action = text('Action') || (text('Agreement Type') && !text('Contract ID') && !text('Prepared Terms Snapshot') ? 'Create draft' : '');
if (!action) { output.set('status', 'No action requested'); return; }
const beforeId = text('Contract ID');
const TERM_FIELDS = [
  'Title', 'Client Legal Name', 'Client Company / Brand', 'Client Address',
  'Client Signer Name', 'Client Signer Email', 'Dulcy Signer Name', 'Dulcy Signer Email',
  'Agreed Service', 'Agreed Scope', 'Contract Currency', 'Billing Frequency',
  'Contract Start Date', 'Agreed Contract Term', 'Agreed Special Terms', 'Agreement Template'
];
const cellText = (row, name) => row.getCellValueAsString(name).trim();
function termsFor(row) {
  return {
    fields: TERM_FIELDS.map(name => [name, cellText(row, name)]),
    fee: row.getCellValue('Contract Fee') ?? null,
    ordered: row.getCellValue('Signing Order') === true,
    testOnly: row.getCellValue('Test Only') === true,
    intake: (row.getCellValue('Client Intake') || []).map(x => x.id),
    pdf: (row.getCellValue('Original PDF') || []).map(x => ({id: x.id, filename: x.filename, size: x.size}))
  };
}
function missingFor(row) {
  const required = ['Title', 'Client Legal Name', 'Client Address', 'Client Signer Name', 'Client Signer Email',
    'Agreed Service', 'Agreed Scope', 'Contract Currency', 'Billing Frequency', 'Contract Start Date',
    'Agreed Contract Term', 'Agreement Template'];
  const missing = required.filter(name => !cellText(row, name));
  if (row.getCellValue('Contract Fee') == null) missing.push('Contract Fee');
  if (!(row.getCellValue('Original PDF') || []).length) missing.push('Original PDF');
  if (cellText(row, 'Dulcy Signer Email') && !cellText(row, 'Dulcy Signer Name')) missing.push('Dulcy Signer Name');
  if (cellText(row, 'Missing / Unconfirmed Terms')) missing.push('Missing / Unconfirmed Terms');
  return missing;
}
function readSnapshot(row) {
  try { const value = JSON.parse(cellText(row, 'Prepared Terms Snapshot')); return value.version === 1 ? value : null; }
  catch { return null; }
}
function sameTerms(a, b) { return JSON.stringify(a) === JSON.stringify(b); }
function matchesContract(snapshot, contract) {
  const fields = Object.fromEntries(snapshot.terms.fields);
  const expected = [{name: fields['Client Signer Name'], email: fields['Client Signer Email'].toLowerCase()}];
  if (fields['Dulcy Signer Email']) expected.push({name: fields['Dulcy Signer Name'], email: fields['Dulcy Signer Email'].toLowerCase()});
  return contract.airtableRecord === recordId && contract.title === fields.Title &&
    contract.testOnly === snapshot.terms.testOnly && contract.ordered === snapshot.terms.ordered &&
    contract.sourceRecord === (snapshot.terms.intake[0] || null) &&
    sameTerms(expected, contract.signers.map(s => ({name:s.name, email:s.email.toLowerCase()})));
}
async function saveDraft(contract) {
  const latest = await table.selectRecordAsync(recordId);
  const snapshot = readSnapshot(latest);
  const valid = snapshot && matchesContract(snapshot, contract) &&
    (!snapshot.contractId || snapshot.contractId === contract.id) &&
    (!snapshot.frozenHash || snapshot.frozenHash === contract.frozenHash);
  const live = !contract.testOnly;
  const unchanged = valid && sameTerms(snapshot.terms, termsFor(latest));
  const review = live ? {
    'Contract Review Status': {name: unchanged && !missingFor(latest).length ? 'Ready for review' : 'Needs confirmation'},
    ...(valid ? {'Prepared Terms Snapshot': JSON.stringify({...snapshot, contractId:contract.id, frozenHash:contract.frozenHash})} : {})
  } : {};
  await table.updateRecordAsync(recordId, {
    'Contract ID': contract.id, Status: {name:contract.status}, 'Frozen SHA-256': contract.frozenHash,
    'Manage Contract': API_ORIGIN + '/admin#contract=' + contract.id,
    'Last Error': live && !unchanged ? 'Draft held: preparation snapshot is missing or details changed. Review the frozen document; use a new Contracts row for revised terms.' : '',
    ...review, ...(latest?.getCellValueAsString('Action') === action ? {Action:null} : {})
  });
}
async function checkInvitationApproval(contract) {
  const latest = await table.selectRecordAsync(recordId);
  if (cellText(latest, 'Action') !== action) throw new Error('Requested action changed; invitation was not sent.');
  if (cellText(latest, 'Contract ID') !== contract.id) throw new Error('Contract binding changed; invitation was not sent.');
  if (contract.testOnly) {
    if (latest.getCellValue('Test Only') !== true) throw new Error('Test mode changed; invitation was not sent.');
    return;
  }
  const prepared=readPreparationSnapshot(latest);
  if(prepared){
    const p=await call('/api/admin/preparations/'+encodeURIComponent(prepared.preparationId));
    if(p.status!=='issued'||p.contractId!==contract.id||p.inputHash!==prepared.inputHash||p.version!==prepared.preparationVersion||cellText(latest,'Frozen SHA-256')!==contract.frozenHash)throw new Error('This preparation does not match the frozen agreement.');
    if(cellText(latest,'Contract Review Status')!=='Approved to send')throw new Error('Approval is required before resending.');
    return;
  }
  const snapshot = readSnapshot(latest);
  let reason = '';
  if (!snapshot?.contractId || !snapshot?.frozenHash) reason = 'The live draft has no completed preparation snapshot.';
  else if (snapshot.contractId !== contract.id || snapshot.frozenHash !== contract.frozenHash ||
           cellText(latest, 'Frozen SHA-256') !== contract.frozenHash || !matchesContract(snapshot, contract))
    reason = 'The frozen document or signers do not match the prepared draft.';
  else if (!sameTerms(snapshot.terms, termsFor(latest))) reason = 'Contract details or the PDF changed after draft creation. Use a new Contracts row and review again.';
  else if (missingFor(latest).length) reason = 'Confirm these fields before sending: ' + missingFor(latest).join(', ') + '.';
  if (reason) {
    await table.updateRecordAsync(recordId, {'Contract Review Status': {name:'Needs confirmation'}});
    throw new Error(reason + ' Invitation was not sent.');
  }
  if (cellText(latest, 'Contract Review Status') !== 'Approved to send')
    throw new Error('Approve the prepared draft by setting Contract Review Status to Approved to send. Invitation was not sent.');
}
function toBase64(bytes) {
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  let result = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const n = (bytes[i] << 16) | ((bytes[i + 1] || 0) << 8) | (bytes[i + 2] || 0);
    result += alphabet[n >>> 18] + alphabet[(n >>> 12) & 63] + (i + 1 < bytes.length ? alphabet[(n >>> 6) & 63] : '=') + (i + 2 < bytes.length ? alphabet[n & 63] : '=');
  }
  return result;
}
async function call(path, body) {
  const result = await fetch(API_ORIGIN + path, { method: body === undefined ? 'GET' : 'POST', headers: { Authorization: 'Bearer ' + key, 'Content-Type': 'application/json' }, ...(body === undefined ? {} : { body: JSON.stringify(body) }) });
  const data = await result.json();
  if (!result.ok) throw new Error(data.error || 'Signing service request failed.');
  return data;
}
function readPreparationSnapshot(row) {
  try { const p=JSON.parse(cellText(row,'Prepared Terms Snapshot')); return p.version===2?p:null; } catch { return null; }
}
function preparationExpectation(p) { return {version:p.preparationVersion,inputHash:p.inputHash,previewHash:p.previewHash,acceptActualSendDate:true}; }
async function preparationAction() {
  const template=text('Agreement Template');
  const choice=text('Agreement Type');
  if(choice){
    if(!['Monthly / Retainer','PPC / PPL'].includes(choice))throw new Error('Choose Monthly / Retainer or PPC / PPL.');
    const health=await call('/health');const version=String(health.version||'').split('.').map(Number);
    if(!(version[0]>0||version[1]>3||(version[1]===3&&version[2]>=2)))throw new Error('Deploy Dulcy Sign 0.3.2 before using the new preparation form. Nothing was sent.');
  }
  if(action==='Create draft'&&!beforeId&&(choice||/^https:\/\/docs\.google\.com\/document\/d\/(15Rua0IOQArSeO_JVThL_tL_t_AwwsMTTHV9fr9F009Y|1WTeo9lDk7MVWVUC22DfJgt10JQU_8FZqhk_bJF6tgNk)(?:\/|$)/.test(template))) {
    const p=await call('/api/admin/preparations/from-airtable/'+recordId,{});
    const latest=await table.selectRecordAsync(recordId);
    await table.updateRecordAsync(recordId, {'Last Error':p.missing.length?'Confirm before sending: '+p.missing.join('; '):'',...(cellText(latest,'Action')===action?{Action:null}:{})});
    output.set('preparationId',p.id); output.set('status',p.status); return true;
  }
  const snapshot=readPreparationSnapshot(record);
  if(action==='Issue invitation'&&!beforeId&&snapshot) {
    const latest=await table.selectRecordAsync(recordId);
    if(cellText(latest,'Action')!==action||cellText(latest,'Contract Review Status')!=='Approved to send')throw new Error('Approve the prepared agreement before requesting an invitation. Nothing was sent.');
    const current=readPreparationSnapshot(latest);
    if(JSON.stringify(current)!==JSON.stringify(snapshot))throw new Error('Preparation changed. Review the current version.');
    const expected=preparationExpectation(current);
    await call('/api/admin/preparations/'+encodeURIComponent(current.preparationId)+'/approve',expected);
    const sent=await call('/api/admin/preparations/'+encodeURIComponent(current.preparationId)+'/issue',expected);
    const c=sent.contract;if(!c)throw new Error('Signing service did not confirm the issued contract.');
    const final=await table.selectRecordAsync(recordId);
    await table.updateRecordAsync(recordId, {'Contract ID':c.id,Status:{name:c.status},'Frozen SHA-256':c.frozenHash,
      'Manage Contract':API_ORIGIN+'/admin#contract='+c.id,'Last Error':'',...(cellText(final,'Action')===action?{Action:null}:{})});
    output.set('contractId',c.id);output.set('status',c.status);return true;
  }
  return false;
}
try {
  if(await preparationAction())return;
  let contract;
  if (action === 'Create draft') {
    contract = await call('/api/admin/contracts/by-airtable/' + recordId);
    if (contract) {
      if (beforeId && beforeId !== contract.id) throw new Error('Contract binding conflict.');
      await saveDraft(contract);
      output.set('contractId', contract.id);
      output.set('status', contract.status);
      return;
    }
    if (beforeId) throw new Error('This record already has a contract ID. Do not replace it.');
    const attachment = record.getCellValue('Original PDF')?.[0];
    const testOnly = record.getCellValue('Test Only') === true;
    let bytes;
    if (attachment) {
      if (attachment.size > 10 * 1024 * 1024) throw new Error('PDF exceeds 10 MB.');
      const url = new URL(attachment.url);
      if (url.protocol !== 'https:' || !/(^|\.)airtableusercontent\.com$/.test(url.hostname)) throw new Error('Unsupported attachment host. Upload the PDF directly to Airtable.');
      const result = await fetch(url.toString());
      if (!result.ok) throw new Error('Could not download the attachment.');
      bytes = new Uint8Array(await result.arrayBuffer());
    } else {
      if (!testOnly) throw new Error('An approved PDF is required for a live contract.');
      const result = await fetch(API_ORIGIN + '/api/admin/sample', { headers: { Authorization: 'Bearer ' + key } });
      if (!result.ok) throw new Error('Could not create the non-binding test PDF.');
      bytes = new Uint8Array(await result.arrayBuffer());
    }
    const signers = [{ name: text('Client Signer Name'), email: text('Client Signer Email') }];
    if (text('Dulcy Signer Email')) signers.push({ name: text('Dulcy Signer Name'), email: text('Dulcy Signer Email') });
    const intake = record.getCellValue('Client Intake')?.[0]?.id;
    if (!testOnly) await table.updateRecordAsync(recordId, {
      'Prepared Terms Snapshot': JSON.stringify({version:1, terms:termsFor(record), contractId:null, frozenHash:null}),
      'Contract Review Status': {name:'Needs confirmation'}
    });
    contract = await call('/api/admin/contracts', { title: text('Title'), signers, pdfBase64: toBase64(bytes), requestKey: 'airtable-' + recordId, testOnly, ordered: record.getCellValue('Signing Order') === true, sourceRecord: intake || null, airtableRecord: recordId });
    await saveDraft(contract);
  } else {
    if (!beforeId) throw new Error('Create a draft first.');
    const path = { 'Issue invitation': 'issue', 'Resend invitation': 'resend', Void: 'void' }[action];
    if (!path) throw new Error('Unsupported action.');
    if (path === 'issue' || path === 'resend') {
      const frozen = await call('/api/admin/contracts/' + encodeURIComponent(beforeId));
      await checkInvitationApproval(frozen);
    }
    await call('/api/admin/contracts/' + encodeURIComponent(beforeId) + '/' + path, {});
    contract = await call('/api/admin/contracts/' + encodeURIComponent(beforeId));
    const latest = await table.selectRecordAsync(recordId);
    await table.updateRecordAsync(recordId, { Status: { name: contract.status }, 'Last Error': '', ...(latest?.getCellValueAsString('Action') === action ? { Action: null } : {}) });
  }
  output.set('contractId', contract.id);
  output.set('status', contract.status);
} catch (error) {
  await table.updateRecordAsync(recordId, { 'Last Error': String(error.message).slice(0,1000) });
  throw error;
}
